/* @component: f-number */
(function () {
  function initNumberInputs() {
    document.querySelectorAll('.f-number').forEach(function (container) {
      if (container.dataset.initialized === 'true') return;
      container.dataset.initialized = 'true';
      const input = container.querySelector('input[type="number"]');
      const decBtn = container.querySelector('.num-btn--dec');
      const incBtn = container.querySelector('.num-btn--inc');
      if (!input) return;
      function updateValue(delta) {
        const min = input.hasAttribute('min') ? parseFloat(input.min) : -Infinity;
        const max = input.hasAttribute('max') ? parseFloat(input.max) : Infinity;
        const step = input.hasAttribute('step') ? parseFloat(input.step) || 1 : 1;
        let val = (parseFloat(input.value) || 0) + delta * step;
        if (val < min) val = min;
        if (val > max) val = max;
        input.value = val;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
      }
      if (decBtn) decBtn.addEventListener('click', function () { updateValue(-1); });
      if (incBtn) incBtn.addEventListener('click', function () { updateValue(1); });
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initNumberInputs);
  } else {
    initNumberInputs();
  }
  setTimeout(initNumberInputs, 300);
})();
/* @end: f-number */
